content.arguments:
{"description":"检查禁用的半角波浪号与 br 标签","command":"$dir='./'
foreach($f in @('99-cross-table.md','99-final-report.md')){
  $p=Join-Path $dir $f
  $t=Get-Content -LiteralPath $p -Raw -Encoding UTF8
  $lines=$t -split "`r?`n"
  $tilde=($lines | Select-String -Pattern '~' -AllMatches | Measure-Object).Count
  $br=($lines | Select-String -Pattern '<br' -CaseSensitive:$false | Measure-Object).Count
  # 表格行（以 | 开头）内部不可能有换行；检查是否有行以 | 结尾但下一行以 | 开头且不是分隔行
  $tbl=$lines | Where-Object { $_ -match '^\s*\|' }
  Write-Output ("{0}: lines={1} tableRows={2} tildeLines={3} brLines={4}" -f $f,$lines.Count,$tbl.Count,$tilde,$br)
}"}

