content.arguments:
{"command":"$dir='./'
foreach($f in @('99-cross-table.md','99-final-report.md')){
  $p=Join-Path $dir $f
  $lines=Get-Content -LiteralPath $p -Encoding UTF8
  $i=0
  foreach($l in $lines){
    $i++
    if($l -match '\d\s?-\s?\d' -or $l -match '[A-Za-z]-[A-Za-z]' -or $l -match '\d\s?—\s?\d'){
      Write-Output ("{0}:{1}: {2}" -f $f,$i,$l.Trim())
    }
  }
}","description":"检查半角连字符是否为区间写法"}

